using System;using System.Diagnostics;using System.IO;using System.Linq;using System.Reflection;using System.Text;using System.Threading;using System.Web.Script.Serialization;
namespace PZ3D {static class GameStartupBridgeTests {
 static void Check(bool ok,string label){Console.WriteLine((ok?"PASS: ":"FAIL: ")+label);if(!ok)throw new Exception(label);}
 static Engine Fixture(string suffix){string root=Path.Combine(LauncherTestPaths.Root,"sb-"+Guid.NewGuid().ToString("N").Substring(0,8));var e=new Engine(Path.Combine(root,"game"),Path.Combine(root,"user"),Path.Combine(root,"data"),true,SteamLaunchOptions.Unavailable,name=>new Process[0]);Directory.CreateDirectory(e.Game);Directory.CreateDirectory(Path.GetDirectoryName(e.Mods));File.WriteAllText(e.Config,"{\"vmArgs\":[]}");File.WriteAllText(e.Mods,"mods\r\n{\r\n mod = Regular,\r\n}\r\nmaps\r\n{\r\n map = LocalMap,\r\n}\r\n",new UTF8Encoding(true));return e;}
 static ProfileLaunchRequest Request(string nonce){var r=new ProfileLaunchRequest{Kind="normal"};typeof(ProfileLaunchRequest).GetField("StartupSessionId",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic).SetValue(r,nonce);return r;}
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();
 static ProfileSessionRecord Record(Engine e){return Json.Deserialize<ProfileSessionRecord>(File.ReadAllText(LaunchProfiles.Journal(e)));}
 static void MarkLaunched(Engine e){var r=Record(e);r.State="launched";File.WriteAllText(LaunchProfiles.Journal(e),Json.Serialize(r));}
 static MethodInfo Method(string name){return typeof(LaunchProfiles).GetMethod(name,BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public);}
 static int Watch(Engine e,string nonce,double seconds){return (int)Method("WatchNormal").Invoke(null,new object[]{e,nonce,TimeSpan.FromSeconds(seconds),50});}
 static Process Find(Engine e,long after){return (Process)Method("FindNormalClient").Invoke(null,new object[]{e.Game,after});}
 static Process StartFixture(Engine e,int milliseconds,string name="ProjectZomboid64.exe",string prefix=""){string path=Path.Combine(e.Game,name);Directory.CreateDirectory(Path.GetDirectoryName(path));if(!File.Exists(path))File.Copy(Assembly.GetExecutingAssembly().Location,path);var child=Process.Start(new ProcessStartInfo(path,prefix+"--bridge-fixture "+milliseconds){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=milliseconds<0});var deadline=Stopwatch.StartNew();while(deadline.ElapsedMilliseconds<500){try{child.Refresh();if(!string.IsNullOrEmpty(child.MainModule.FileName))break;}catch{}Thread.Sleep(10);}return child;}
 static void Run(){
  Check(typeof(ProfileLaunchRequest).GetField("StartupSessionId",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)!=null&&Method("LaunchNormal")!=null,"normal and profile entry accept an internal startup session");
  var e=Fixture("stage");byte[] original=File.ReadAllBytes(e.Mods);string nonce=new string('a',32);LaunchProfiles.Stage(e,Request(nonce));var record=Record(e);string[] request=File.ReadAllLines(Path.Combine(e.User,"Lua","OrangeLauncherSession.request.txt"));
  Check(record.Nonce==nonce&&request.Length==12&&request[1]==nonce&&request[3]=="normal","normal bridge keeps ORANGE1 and exact startup nonce");
  Check(File.ReadAllText(e.Mods).Contains("Regular")&&File.ReadAllText(e.Mods).Contains("LocalMap")&&record.State=="prepared","normal staging preserves local mods/maps and does not claim ready");
  LaunchProfiles.Recover(e,true);Check(File.ReadAllBytes(e.Mods).SequenceEqual(original)&&!LaunchProfiles.Pending(e),"normal recovery restores exact original bytes");
  foreach(string bad in new[]{"X",new string('A',32),new string('a',33)}){bool refused=false;try{LaunchProfiles.Stage(e,Request(bad));}catch{refused=true;}Check(refused&&!LaunchProfiles.Pending(e),"malformed startup nonce rejected before staging");}
  LaunchProfiles.Stage(e,new ProfileLaunchRequest{Kind="save",Mode="Sandbox",Save="Fixture"});Check(Record(e).Nonce.Length==32,"existing profile callers retain generated nonces");LaunchProfiles.Recover(e,true);
  LaunchProfiles.Stage(e,Request(nonce));MarkLaunched(e);LaunchProfiles.Recover(e);Check(LaunchProfiles.Pending(e),"launcher reopening during Steam delay preserves the waiting bridge");var timer=Stopwatch.StartNew();int result=Watch(e,nonce,.25);Check(result==0&&timer.ElapsedMilliseconds>=200&&!LaunchProfiles.Pending(e),"Steam no-client timeout is bounded and restores staged files");
  LaunchProfiles.Stage(e,Request(nonce));MarkLaunched(e);using(var foreign=StartFixture(e,1000,"unrelated.exe")){Check(Find(e,DateTime.UtcNow.AddSeconds(-5).Ticks)==null,"unrelated executable cannot satisfy normal-client wait");foreign.WaitForExit();}
  var other=Fixture("foreign");using(var foreign=StartFixture(other,600)){Check(Find(e,DateTime.UtcNow.AddSeconds(-5).Ticks)==null,"same client name from another directory cannot satisfy the wait");foreign.WaitForExit();}
  using(var server=StartFixture(e,-1,Path.Combine("jre64","bin","java.exe"),"-cp fixture zombie.network.GameServer ")){Check(GameProcessGuard.ReadJavaRole(e.Game,"java",server.MainModule.FileName,server)==JavaProcessRole.Server,"controlled same-runtime server has verified PID birth and command role");Check(Find(e,DateTime.UtcNow.AddSeconds(-5).Ticks)==null,"same-runtime dedicated server cannot satisfy the client wait");server.StandardInput.WriteLine("exit");Check(server.WaitForExit(5000),"owned server fixture exits naturally");}
  using(var unrelatedJava=StartFixture(e,600,Path.Combine("jre64","bin","java.exe"))){Check(Find(e,DateTime.UtcNow.AddSeconds(-5).Ticks)==null,"same-runtime unknown Java cannot satisfy the client wait");unrelatedJava.WaitForExit();}
  using(var old=StartFixture(e,1000)){Check(Find(e,DateTime.UtcNow.AddSeconds(1).Ticks)==null,"client born before this session cannot satisfy the wait");old.WaitForExit();}
  var delayed=new Thread(()=>{Thread.Sleep(250);using(var child=StartFixture(e,650)){Thread.Sleep(200);Check(LaunchProfiles.Pending(e),"running client retains temporary bridge until exit");child.WaitForExit();}});delayed.Start();timer.Restart();result=Watch(e,nonce,4);delayed.Join();Check(result==0&&timer.ElapsedMilliseconds>=800&&!LaunchProfiles.Pending(e)&&File.ReadAllBytes(e.Mods).SequenceEqual(original),"delayed real client is tracked to exit before exact recovery");
  var failed=Fixture("open-fail");File.Copy(Assembly.GetExecutingAssembly().Location,Path.Combine(failed.Game,"ProjectZomboid64.exe"));byte[] beforeFailure=File.ReadAllBytes(failed.Mods);var native=new Engine(failed.Game,failed.User,failed.Data,false,SteamLaunchOptions.Unavailable,name=>new Process[0]);bool opened=false,thrown=false;try{LaunchProfiles.LaunchNormal(native,nonce,()=>{opened=true;Check(LaunchProfiles.Pending(native)&&Record(native).State=="prepared","Steam opens only after durable staging");throw new InvalidOperationException("synthetic Steam open failure");});}catch(InvalidOperationException){thrown=true;}Check(opened&&thrown&&!LaunchProfiles.Pending(native)&&File.ReadAllBytes(native.Mods).SequenceEqual(beforeFailure),"Steam open failure restores exact defaults and removes the private request");
  LaunchProfiles.Stage(e,Request(new string('b',32)));MarkLaunched(e);Check(Watch(e,nonce,.1)==0&&LaunchProfiles.Pending(e),"old Steam watcher cannot clean a newer session");LaunchProfiles.Recover(e,true);
 }
 public static int Main(string[] args){int fixtureArgument=Array.IndexOf(args,"--bridge-fixture");if(fixtureArgument>=0&&fixtureArgument+1<args.Length){int duration=int.Parse(args[fixtureArgument+1]);if(duration<0)Console.ReadLine();else Thread.Sleep(duration);return 0;}try{Run();return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}}
